content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --border-color: #e5e7eb;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px;
}

.header {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 24px;
  background-color: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

@media (min-width: 768px) {
  .header {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
}

.chart-card {
  background-color: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  margin-bottom: 24px;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 18px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  background-color: var(--card-bg);
  color: var(--text-main);
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn:hover {
  background-color: var(--bg-color);
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
  border-color: var(--primary-color);
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: 16px;
  margin-bottom: 24px;
}

@media (min-width: 640px) {
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .stats-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.stat-card {
  background-color: var(--card-bg);
  padding: 20px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.stat-value {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--primary-color);
}

.stat-label {
  font-size: 0.875rem;
  color: var(--text-muted);
  font-weight: 500;
}

import { useState } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  CartesianGrid,
} from 'recharts';
import './index.css';

interface MonthlySales {
  month: string;
  sales: number;
}

const initialData: MonthlySales[] = [
  { month: '1月', sales: 120 },
  { month: '2月', sales: 145 },
  { month: '3月', sales: 190 },
  { month: '4月', sales: 210 },
  { month: '5月', sales: 180 },
  { month: '6月', sales: 230 },
  { month: '7月', sales: 250 },
  { month: '8月', sales: 270 },
  { month: '9月', sales: 220 },
  { month: '10月', sales: 240 },
  { month: '11月', sales: 290 },
  { month: '12月', sales: 350 },
];

const themes = [
  { name: 'インディゴ', color: '#4f46e5' },
  { name: 'エメラルド', color: '#10b981' },
  { name: 'スカイブルー', color: '#0284c7' },
  { name: 'アンバー', color: '#d97706' },
];

export default function App() {
  const [data, setData] = useState<MonthlySales[]>(initialData);
  const [themeIndex, setThemeIndex] = useState<number>(0);

  const currentTheme = themes[themeIndex];

  const handleRandomize = () => {
    const newData = data.map((item) => ({
      ...item,
      sales: Math.floor(Math.random() * 250) + 100,
    }));
    setData(newData);
  };

  const handleNextTheme = () => {
    setThemeIndex((prev) => (prev + 1) % themes.length);
  };

  // 統計計算
  const totalSales = data.reduce((sum, item) => sum + item.sales, 0);
  const averageSales = Math.round(totalSales / data.length);
  const maxSalesItem = data.reduce((max, item) => (item.sales > max.sales ? item : max), data[0]);
  const minSalesItem = data.reduce((min, item) => (item.sales < min.sales ? item : min), data[0]);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">年間売上ダッシュボード (1月〜12月)</h1>
        <div className="controls">
          <button className="btn btn-primary" onClick={handleRandomize}>
            データをランダム更新
          </button>
          <button className="btn" onClick={handleNextTheme}>
            テーマ切替 ({currentTheme.name})
          </button>
        </div>
      </header>

      <div className="stats-grid">
        <div className="stat-card">
          <span className="stat-value" style={{ color: currentTheme.color }}>
            {totalSales} 万円
          </span>
          <span className="stat-label">年間総売上</span>
        </div>
        <div className="stat-card">
          <span className="stat-value" style={{ color: currentTheme.color }}>
            {averageSales} 万円
          </span>
          <span className="stat-label">月平均売上</span>
        </div>
        <div className="stat-card">
          <span className="stat-value" style={{ color: currentTheme.color }}>
            {maxSalesItem.month} ({maxSalesItem.sales}万円)
          </span>
          <span className="stat-label">最高売上月</span>
        </div>
        <div className="stat-card">
          <span className="stat-value" style={{ color: currentTheme.color }}>
            {minSalesItem.month} ({minSalesItem.sales}万円)
          </span>
          <span className="stat-label">最低売上月</span>
        </div>
      </div>

      <div className="chart-card">
        <div style={{ width: '100%', height: 400 }}>
          <ResponsiveContainer>
            <BarChart data={data} margin={{ top: 20, right: 30, left: 0, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="month" />
              <YAxis unit="万円" />
              <Tooltip
                formatter={(value: number) => [`${value} 万円`, '売上']}
                contentStyle={{ borderRadius: '8px', border: '1px solid #e5e7eb' }}
              />
              <Bar dataKey="sales" fill={currentTheme.color} radius={[6, 6, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
}
